use serde::Serialize;
#[derive(Clone,Copy,Debug,Serialize)]
#[serde(rename_all="camelCase")]
pub struct HohmannTransfer{pub departure_delta_v_m_s:f64,pub arrival_delta_v_m_s:f64,pub total_delta_v_m_s:f64,pub transfer_time_seconds:f64,pub transfer_semi_major_axis_m:f64}
pub fn hohmann_transfer(mu:f64,r1:f64,r2:f64)->Result<HohmannTransfer,String>{
 for(value,name)in[(mu,"primaryMu"),(r1,"initialRadiusM"),(r2,"targetRadiusM")]{if !value.is_finite()||value<=0.0{return Err(format!("{name} must be finite and positive."))}}
 if r1==r2{return Ok(HohmannTransfer{departure_delta_v_m_s:0.0,arrival_delta_v_m_s:0.0,total_delta_v_m_s:0.0,transfer_time_seconds:0.0,transfer_semi_major_axis_m:r1})}
 let a=(r1+r2)*0.5;let vi=(mu/r1).sqrt();let vt=(mu/r2).sqrt();let v1=(mu*(2.0/r1-1.0/a)).sqrt();let v2=(mu*(2.0/r2-1.0/a)).sqrt();let d1=(v1-vi).abs();let d2=(vt-v2).abs();
 Ok(HohmannTransfer{departure_delta_v_m_s:d1,arrival_delta_v_m_s:d2,total_delta_v_m_s:d1+d2,transfer_time_seconds:std::f64::consts::PI*(a.powi(3)/mu).sqrt(),transfer_semi_major_axis_m:a})
}
pub fn circular_orbit_speed(mu:f64,radius:f64)->Result<f64,String>{for(value,name)in[(mu,"mu"),(radius,"radiusM")]{if !value.is_finite()||value<=0.0{return Err(format!("{name} must be finite and positive."))}}Ok((mu/radius).sqrt())}
pub fn thrust_to_weight_ratio(thrust:f64,mass:f64,gravity:f64)->Result<f64,String>{if !thrust.is_finite()||thrust<0.0{return Err("thrustN must be finite and non-negative.".into())}for(value,name)in[(mass,"massKg"),(gravity,"gravityMS2")]{if !value.is_finite()||value<=0.0{return Err(format!("{name} must be finite and positive."))}}Ok(thrust/(mass*gravity))}
pub fn orbital_period(a:f64,mu:f64)->Result<f64,String>{for(value,name)in[(a,"semiMajorAxisM"),(mu,"mu")]{if !value.is_finite()||value<=0.0{return Err(format!("{name} must be finite and positive."))}}Ok(std::f64::consts::TAU*(a.powi(3)/mu).sqrt())}
pub fn plane_change_delta_v(speed:f64,angle:f64)->Result<f64,String>{if !speed.is_finite()||speed<=0.0{return Err("speedMS must be finite and positive.".into())}if !angle.is_finite()||angle<0.0||angle>std::f64::consts::PI{return Err("angleRadians must be in [0, pi].".into())}Ok(2.0*speed*(angle*0.5).sin())}
#[cfg(test)]mod tests{use super::*;#[test]fn zero_thrust_is_a_valid_zero_twr_state(){assert_eq!(thrust_to_weight_ratio(0.0,1000.0,9.80665).unwrap(),0.0);assert!(thrust_to_weight_ratio(-1.0,1000.0,9.80665).is_err());assert!(thrust_to_weight_ratio(f64::NAN,1000.0,9.80665).is_err());}#[test]fn earth_to_mars_hohmann_has_positive_burns(){let x=hohmann_transfer(1.32712440018e20,149597870700.0,227939200000.0).unwrap();assert!(x.departure_delta_v_m_s>0.0&&x.arrival_delta_v_m_s>0.0);assert_eq!(x.total_delta_v_m_s,x.departure_delta_v_m_s+x.arrival_delta_v_m_s);assert!(x.transfer_time_seconds>0.0)}#[test]fn equal_radius_transfer_is_zero(){let x=hohmann_transfer(1.0,10.0,10.0).unwrap();assert_eq!(x.total_delta_v_m_s,0.0);assert_eq!(x.transfer_time_seconds,0.0)}#[test]fn plane_change_matches_vector_delta(){assert!((plane_change_delta_v(7500.0,std::f64::consts::FRAC_PI_2).unwrap()-7500.0*2.0_f64.sqrt()).abs()<1e-10)}}
